function TrendArrow({ trend }: { trend: MetricTrend }) {
  if (trend === "neutral") return null
  return (
    <svg
      className={cn(
        "h-3 w-3",
        trend === "up" ? "rotate-0 text-emerald-500" : "rotate-180 text-destructive",
